import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { gunzipSync } from "node:zlib";
import { afterEach, expect, it, vi } from "vitest";
import {
  decodeManagementPage,
  managementPageMediaType,
} from "../src/managementQueryWire";
import { readManagementPage } from "../src/managementQuery";
import { subFilterDefaults } from "../src/sub2apiPreferences";

// Generated by the actual Go encoder from synthetic typed results, not a
// duplicate JavaScript encoder. Includes Unicode, aliases, zero values and nulls.
const fixture = () =>
  JSON.parse(
    gunzipSync(
      readFileSync(
        resolve("analytics-api/testdata/management-page-wire.json.gz"),
      ),
    ).toString(),
  );
afterEach(() => vi.unstubAllGlobals());

it("restores every complete Go page field without sharing mutable result objects", () => {
  const { page, wire } = fixture();
  const decoded = decodeManagementPage(wire);
  expect(decoded).toStrictEqual(page);
  const message = decoded.rows[0].checks[0].result!.availability.message;
  decoded.rows[0].checks[0].result!.availability.message = "local edit";
  expect(decoded.rows[0].target.models![0].result!.availability.message).toBe(
    message,
  );
  expect(decoded.rows[1].checks[0].result!.availability.message).toBe(message);
  expect(decodeManagementPage(wire)).toStrictEqual(page);
  expect(decoded.rows[2].target.models).toBeNull();
  expect(decoded.rows[0].target.models![2].result).toBeNull();
});

it("negotiates v3 while accepting complete v1 and v2 pages", async () => {
  const { page, wire, columns } = fixture();
  for (const response of [page, wire, columns]) {
    vi.stubGlobal(
      "fetch",
      vi.fn(async (_url: string, init: RequestInit) => {
        expect(new Headers(init.headers).get("Accept")).toBe(
          managementPageMediaType,
        );
        expect(init.cache).toBe("no-cache");
        return Response.json(response);
      }),
    );
    expect(
      await readManagementPage(
        subFilterDefaults,
        "",
        new AbortController().signal,
      ),
    ).toStrictEqual(page);
  }
});

it("rejects malformed reference tables and conflicting evidence before publishing", async () => {
  const changes: ((wire: any) => void)[] = [
    (w) => {
      delete w.results;
    },
    (w) => {
      w.results = [];
    },
    (w) => {
      w.results[0] = null;
    },
    (w) => {
      w.results[0].availability = null;
    },
    (w) => {
      w.results[0].quality = [];
    },
    (w) => {
      w.rows[0].target.result_ref = -1;
    },
    (w) => {
      w.rows[0].target.result_ref = 0.5;
    },
    (w) => {
      w.rows[0].target.result_ref = "0";
    },
    (w) => {
      delete w.rows[0].target.result_ref;
    },
    (w) => {
      w.rows[0].target.result = {};
    },
    (w) => {
      w.rows[0].target.models = {};
    },
    (w) => {
      w.rows[0].target.models[0].result_ref = 100000;
    },
    (w) => {
      delete w.rows[0].checks[0].result_ref;
    },
    (w) => {
      w.rows[0].checks[0].result = {};
    },
    (w) => {
      w.rows[0].selected.result_ref = 100000;
    },
    (w) => {
      w.rows[0].selected = null;
    },
  ];
  for (const change of changes) {
    const { wire } = fixture();
    change(wire);
    vi.stubGlobal(
      "fetch",
      vi.fn(async () => Response.json(wire)),
    );
    await expect(
      readManagementPage(subFilterDefaults, "", new AbortController().signal),
    ).rejects.toThrow("分页数据不完整");
  }
});

it("restores every column-encoded field from the actual Go encoder", () => {
  const { page, columns } = fixture();
  const restored = decodeManagementPage(columns);
  expect(restored).toStrictEqual(page);
  restored.rows[0].checks[0].result!.availability.message = "local edit";
  expect(decodeManagementPage(columns)).toStrictEqual(page);
  expect(restored.rows[1].checks[0].result!.availability.message).toBe(
    page.rows[1].checks[0].result.availability.message,
  );
});

it("rejects malformed columns before publishing any page", () => {
  const cases: ((wire: any) => void)[] = [
    (w) => (w.result_fields.count = -1),
    (w) => (w.result_fields.count = Number.MAX_SAFE_INTEGER),
    (w) => w.result_fields.fields.push(w.result_fields.fields[0]),
    (w) => w.result_fields.columns[0].pop(),
    (w) => (w.result_fields.columns[0][0] = [1, 2]),
    (w) => (w.result_fields.columns[0][0] = null),
    (w) => w.quality.count++,
    (w) => (w.availability.columns = null),
    (w) => (w.results = []),
    (w) => (w.result_fields.fields[0] = "availability"),
  ];
  for (const change of cases) {
    const { columns } = fixture();
    change(columns);
    expect(() => decodeManagementPage(columns)).toThrow("分页数据不完整");
  }
});

it.each(["current", "old-request", "missing", "bad-time"])("requires this read's nonce before accepting a validated representation (%s)", async mode=>{
  const {page,columns}=fixture();
  columns.read_at_ms=0;
  vi.stubGlobal("fetch",vi.fn(async(_url:string,init:RequestInit)=>{
    const requestId=new Headers(init.headers).get("X-Console-Request-ID")!;
    const headers=new Headers();
    if(mode!=="missing")headers.set("X-Console-Validated-Request-ID",mode==="old-request"?"older-request":requestId);
    headers.set("X-Console-Read-At-Ms",mode==="bad-time"?"NaN":"999");
    expect(init.cache).toBe("no-cache");
    return Response.json(columns,{headers});
  }));
  const request=readManagementPage(subFilterDefaults,"",new AbortController().signal);
  if(mode==="current")expect(await request).toStrictEqual({...page,read_at_ms:999});
  else await expect(request).rejects.toThrow("实时核验失败");
});
